import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'5eAXaJha93EuQsvd2SJn',titulo:'Ômega 3 Epa Dha 120 Cápsulas Dark Lab',listing:'MLB5864818802'},{id:'5FMVdsnRQIuJYsUfNJU9',titulo:'Tenis Caminhada Academia Skate Suede Couro Xl Envio Já',listing:'MLB5049422013'},{id:'5G8Rs89UnBehBYVatnan',titulo:'Kit 9 Pares Meias Puma Sapatilha Soquete Invisível Original',listing:'MLB3240424598'}];
test('triagem53 preserva campos operacionais, exige mesma identidade e é idempotente',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('omega3 não promete eficácia, prescreve consumo ou presume irregularidade',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/nem prescrevemos idade, dose ou horário/);assert.match(x.comentario,/nem concluímos que seja irregular/);assert.doesNotMatch(x.pros,/auxilia|alta qualidade|rico|imun|cardio|cerebr|sem glúten/i);});
test('PM não vira outra marca ou promessa de envio ou desempenho esportivo',()=>{const x=correctProductData(rows[1]);assert.match(x.titulo,/Tênis PM anunciado/);assert.doesNotMatch(x.titulo,/Puma|envio|caminhada|academia|skate/i);assert.match(x.comentario,/Não interpretamos PM como outra marca/);assert.doesNotMatch(x.pros,/couro|confort|aderência|envio/i);});
test('meias não certificam autenticidade nem ajuste universal',()=>{const x=correctProductData(rows[2]);assert.doesNotMatch(x.titulo,/original/i);assert.match(x.comentario,/nem concluímos que seja falsificado/);assert.match(x.comentario,/não significa que uma única variante sirva/);assert.doesNotMatch(x.pros,/original|autêntic|garant|universal/i);});
